// real, src/server.ts onTcp
private onTcp(s: net.Socket) {
  this.sockets.add(s);
  s.setTimeout(this.opts.tcpIdleMs ?? 10_000, () => s.destroy());
  s.on("close", () => this.sockets.delete(s));
  s.on("error", () => {});
  const reader = new LengthPrefixedReader();
  s.on("data", (chunk) => {
    for (const frame of reader.feed(chunk)) {
      void this.handle(frame, "tcp").then((out) => {
        if (out && !s.destroyed) s.write(frameTcp(out));
      });
    }
  });
}

// illustrative (NOT in the repo): in-flight dedupe in front of Resolver.resolve
const inflight = new Map<string, Promise<Resolution>>();
function resolveDeduped(r: Resolver, name: string, type: number): Promise<Resolution> {
  const key = `${name.toLowerCase()}|${type}`;
  let p = inflight.get(key);
  if (!p) {
    p = r.resolve(name, type).finally(() => inflight.delete(key));
    inflight.set(key, p);
  }
  return p;
}

