// solution: test/framing.test.ts (new file)
import { describe, expect, it } from "vitest";
import { LengthPrefixedReader, frameTcp } from "../src/transport.js";

const m1 = Buffer.from("hello dns");
const m2 = Buffer.from([0, 1, 2, 3, 4]);

describe("LengthPrefixedReader", () => {
  it("frameTcp writes a 2-byte big-endian length", () => {
    const f = frameTcp(Buffer.alloc(300));
    expect(f.readUInt16BE(0)).toBe(300);
    expect(f.length).toBe(302);
  });

  it("byte by byte: nothing until the last byte, then exactly one frame", () => {
    const r = new LengthPrefixedReader();
    const bytes = frameTcp(m1);
    for (let i = 0; i < bytes.length - 1; i++) expect(r.feed(bytes.subarray(i, i + 1))).toEqual([]);
    expect(r.feed(bytes.subarray(bytes.length - 1))).toEqual([m1]);
    expect(r.pending).toBe(0);
  });

  it("two frames in one chunk, plus half of a third", () => {
    const r = new LengthPrefixedReader();
    const third = frameTcp(m1);
    const out = r.feed(Buffer.concat([frameTcp(m1), frameTcp(m2), third.subarray(0, 4)]));
    expect(out).toEqual([m1, m2]);
    expect(r.pending).toBe(4);
    expect(r.feed(third.subarray(4))).toEqual([m1]);
  });

  it("returned frames are copies", () => {
    const r = new LengthPrefixedReader();
    const chunk = frameTcp(m1);
    const [f] = r.feed(chunk);
    chunk[2] = 0x58;
    expect(f).toEqual(m1);
  });
});

// solution sketch (NOT in the repo): token bucket keyed by client IP
export class RateLimiter {
  private readonly buckets = new Map<string, { tokens: number; at: number }>();
  constructor(private readonly capacity: number, private readonly perSecond: number,
              private readonly maxClients = 10_000, private readonly now = () => Date.now()) {}
  allow(ip: string): boolean {
    const t = this.now();
    let b = this.buckets.get(ip);
    if (!b) {
      if (this.buckets.size >= this.maxClients) this.buckets.delete(this.buckets.keys().next().value!);
      b = { tokens: this.capacity, at: t };
      this.buckets.set(ip, b);
    }
    b.tokens = Math.min(this.capacity, b.tokens + ((t - b.at) / 1000) * this.perSecond);
    b.at = t;
    if (b.tokens < 1) return false;
    b.tokens -= 1;
    return true;
  }
}

